using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using WarframeBuilds.Data;
using WarframeBuilds.Models;
namespace WarframeBuilds.Services;

// Curated WFCD snapshot, embedded for offline startup. Existing records and user references are preserved.
public static class CatalogSeeder
{
 public static async Task SeedAsync(ApplicationDbContext context)
 {
  var frameNames = (await context.Warframes.Select(x => x.Name).ToListAsync()).ToHashSet(StringComparer.OrdinalIgnoreCase);
  var existingWeapons = await context.Weapons.ToListAsync();
  var weaponNames = existingWeapons.Select(x => x.Name).ToHashSet(StringComparer.OrdinalIgnoreCase);
  foreach (var weapon in existingWeapons.Where(x => x.Category == "Melee" && (x.WeaponType == "Melee" || string.IsNullOrWhiteSpace(x.WeaponType))))
   weapon.WeaponType = weapon.Name switch { "Skana" => "Sword", "Bo" => "Staff", "Dual Zoren" => "Dual Swords", _ => weapon.WeaponType };
  var modNames = (await context.Mods.Select(x => x.Name).ToListAsync()).ToHashSet(StringComparer.OrdinalIgnoreCase);
  context.Warframes.AddRange(JsonSerializer.Deserialize<List<Warframe>>(FramesJson)!.Where(x => frameNames.Add(x.Name)));
  context.Weapons.AddRange(JsonSerializer.Deserialize<List<Weapon>>(WeaponsJson)!.Where(x => weaponNames.Add(x.Name)));
  context.Mods.AddRange(JsonSerializer.Deserialize<List<Mod>>(ModsJson)!.Where(x => modNames.Add(x.Name)));
  // Enrich legacy starter records in place: references from saved builds keep their IDs.
  var existingMods = await context.Mods.ToListAsync();
  foreach(var seed in JsonSerializer.Deserialize<List<Mod>>(ModsJson)!)
  {
   var row=existingMods.FirstOrDefault(x=>x.Name==seed.Name);
   if(row!=null && (string.IsNullOrWhiteSpace(row.Compatibility)||string.IsNullOrWhiteSpace(row.LevelStatsJson)))
   {row.Compatibility=seed.Compatibility;row.Type=seed.Type;row.IsExilus=seed.IsExilus;row.LevelStatsJson=seed.LevelStatsJson;row.UniqueName=seed.UniqueName;row.BaseDrain=seed.BaseDrain;row.MaxRank=seed.MaxRank;row.Polarity=seed.Polarity;}
  }
  foreach(var seed in JsonSerializer.Deserialize<List<Weapon>>(WeaponsJson)!)
  {
   var row=existingWeapons.FirstOrDefault(x=>x.Name==seed.Name);
   if(row!=null && row.BaseDamage<=0)
   {row.WeaponType=seed.WeaponType;row.BaseDamage=seed.BaseDamage;row.CriticalChance=seed.CriticalChance;row.CriticalMultiplier=seed.CriticalMultiplier;row.StatusChance=seed.StatusChance;row.FireRate=seed.FireRate;row.MagazineSize=seed.MagazineSize;row.ReloadTime=seed.ReloadTime;row.ImageName=seed.ImageName;row.UniqueName=seed.UniqueName;}
  }
  var guideTitles = (await context.Guides.Select(x => x.Title).ToListAsync()).ToHashSet(StringComparer.OrdinalIgnoreCase);
  foreach (var guide in StarterGuides()) if (guideTitles.Add(guide.Title)) context.Guides.Add(guide);
  await context.SaveChangesAsync();
 }
 private static IEnumerable<Guide> StarterGuides()
 {
  yield return new Guide { Title = "Первый билд: вместимость и полярности", Category = "Основы", Author = "Редакция Tenno Forge", IsFeatured = true,
   Description = "Как выбрать ранг мода, реактор и полярность слота.",
   Content = "Начните с выбора варфрейма или оружия. Обычный предмет 30 ранга имеет 30 единиц вместимости; реактор или катализатор удваивает её. Увеличивайте ранг выбранного мода постепенно и следите за итоговой стоимостью. Совпадение полярности уменьшает расход с округлением вверх, несовпадение увеличивает его. Аура и стойка добавляют вместимость. Forma позволяет изменить полярность слота.\n\nРасчёты на сайте упрощены: это планировщик, а не полный симулятор Warframe. Проверяйте актуальные значения и взаимодействия в игре." };
  yield return new Guide { Title = "Варфрейм: баланс способностей и выживаемости", Category = "Варфреймы", Author = "Редакция Tenno Forge", IsFeatured = true,
   Description = "Сила, длительность, радиус и энергоэффективность без лишней сложности.",
   Content = "Выберите подходящие способности и задачу миссии. Intensify повышает силу, Continuity — длительность, Stretch — радиус, Streamline — энергоэффективность. Vitality, Redirection и Steel Fiber помогают настроить выживаемость, а Flow увеличивает запас энергии. Не все способности одинаково зависят от каждой характеристики.\n\nВместимость — ограничение, а не цель: оставьте место для защиты и удобства. Формулы характеристик упрощены; пассивные способности, особые взаимодействия и временные бонусы могут не учитываться. Сверяйтесь с игрой." };
  yield return new Guide { Title = "Оружие: урон, критические попадания и статус", Category = "Оружие", Author = "Редакция Tenno Forge", IsFeatured = true,
   Description = "Основа сборки для винтовки, пистолета и ближнего боя.",
   Content = "Начните с базового урона: Serration для винтовки, Point Blank для дробовика, Hornet Strike для пистолета или Pressure Point для ближнего боя. Затем сравните критический шанс и статус предмета. Point Strike и Vital Sense подходят оружию с хорошими критическими параметрами. Элементальные моды добавляют урон, а их порядок в игре влияет на сочетания элементов.\n\nПоказанные урон и DPS — упрощённые оценки. Броня, сопротивления противника, статусные эффекты, мультивыстрел, комбо, альтернативные атаки и условные бонусы не моделируются полностью. Оценка не заменяет проверку в Симулякруме." };
 }
